class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if not prices: return 0
        if k >= len(prices) // 2:
            return sum(max(0, prices[i] - prices[i-1]) for i in range(1, len(prices)))
        dp = [[0]*(k+1) for _ in range(len(prices))]
        for j in range(1, k+1):
            max_diff = -prices[0]
            for i in range(1, len(prices)):
                dp[i][j] = max(dp[i-1][j], prices[i] + max_diff)
                max_diff = max(max_diff, dp[i-1][j-1] - prices[i])
        return dp[-1][-1]

reference_solution.javascript:
function maxProfit(k, prices) {
    if (!prices || prices.length === 0) return 0;
    if (k >= Math.floor(prices.length / 2)) {
        let profit = 0;
        for (let i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i-1]) profit += prices[i] - prices[i-1];
        }
        return profit;
    }
    const dp = Array.from({length: prices.length}, () => new Array(k+1).fill(0));
    for (let j = 1; j <= k; j++) {
        let maxDiff = -prices[0];
        for (let i = 1; i < prices.length; i++) {
            dp[i][j] = Math.max(dp[i-1][j], prices[i] + maxDiff);
            maxDiff = Math.max(maxDiff, dp[i-1][j-1] - prices[i]);
        }
    }
    return dp[prices.length-1][k];
}
